import itertools

T, F, B = 0, 1, 2

def search(k, max_results=20):
    pairs = list(itertools.combinations(range(k), 2))
    npairs = len(pairs)
    # enumerate all proper 3-colorings
    colorings = []
    for col in itertools.product(range(3), repeat=k):
