    for emask in range(1 << npairs):
        edges = [pairs[i] for i in range(npairs) if (emask >> i) & 1]
        # for each edge mask, determine for each constraint (litcolors mask, att_b, att_l) colorability
        # precompute set of colorings satisfying edge constraints
        valid = [c for c in colorings if all(c[u] != c[v] for u, v in edges)]
        if not valid:
            continue
        for att_l in itertools.permutations(range(k), 3):
            for att_b in range(k):
                if att_b in att_l:
                    continue
                ok_all = True
                for mask in range(8):
                    litcolors = [T if (mask >> i) & 1 else F for i in range(3)]
                    want = any(x == T for x in litcolors)
                    sat = False
                    for c in valid:
                        if c[att_b] != B: continue
                        if all(c[att_l[i]] == litcolors[i] for i in range(3)):
                            sat = True; break
                    if sat != want:
                        ok_all = False; break
                if ok_all:
                    found.append((edges, att_l, att_b))
                    if len(found) >= max_results:
                        return found
    return found

for k in [5, 6]:
    f = search(k)
    print("k =", k, "found:", len(f))
    for x in f[:5]:
        print(x)
    if f:
        break
