# Independent method 1: backtracking with MRV (different from test's naive bt)
def colorable_mrv(n, edges):
    adj=[set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    col={}
    def bt():
        if len(col)==n: return True
        # pick uncolored vertex with most colored neighbors
        best=None;bestd=-1
        for v in range(n):
            if v in col: continue
            d=sum(1 for w in adj[v] if w in col)
            if d>bestd: bestd=d;best=v
        for c in range(3):
            if all(col.get(w)!=c for w in adj[best]):
                col[best]=c
                if bt(): return True
                del col[best]
        return False
    return bt()

print("MRV backtracking colorable:", colorable_mrv(n,edges))

# Independent method 2: encode coloring as SAT and solve by enumeration of 3^n but pruned
# Use a direct constraint check via brute force over 3 colors but with early pruning
def colorable_bt2(n, edges):
    adj=[[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v); adj[v].append(u)
    c=[-1]*n
    def bt(i):
        if i==n: return True
        for k in range(3):
            if all(c[j]!=k for j in adj[i] if j<i):
                c[i]=k
                if bt(i+1): return True
                c[i]=-1
        return False
    return bt(0)
print("naive backtracking colorable:", colorable_bt2(n,edges))

# Sanity checks of solver on known graphs
